// HakSpring Romanizer (Romaine) - 「蘿蔓生菜」客語羅馬字轉換器
// Written by Roo, the AI Software Engineer
// Based on spec 1.4 generated by Gemini 2.5 Pro based on ideas of Aiuanyu

document.addEventListener('DOMContentLoaded', () => {
  let romanizerSelectedDialect = '四縣';
  const ROMANIZER_JOINING_MODE_KEY = 'romanizerJoiningMode';
  let romanizerJoiningMode = 'none';

  // --- History variables ---
  let history = [];
  let historyIndex = -1;

  // DOM Elements
  const showRomanizerBtn = document.getElementById('showRomanizerBtn');
  const romanizerContainer = document.getElementById('romanizerContainer');
  const romanizerCloseBtn = document.getElementById('romanizerCloseBtn');
  const romanizerStartBtn = document.getElementById('romanizer-start-btn');
  const segmentationWorkspace = document.getElementById('segmentation-workspace');
  const copyRomanizerResultBtn = document.getElementById('copy-romanizer-result-btn');
  const romanizerDialectSelector = document.getElementById('romanizer-dialect-selector');
  const romanizerJoiningModeSelector = document.getElementById('romanizer-joining-mode-selector');
  const romanizerInput = document.getElementById('romanizer-input');
  const romanizerOutput = document.getElementById('romanizer-output');
  const romanizerUndoBtn = document.getElementById('romanizer-undo-btn');
  const romanizerRedoBtn = document.getElementById('romanizer-redo-btn');

  const savedJoiningMode = localStorage.getItem(ROMANIZER_JOINING_MODE_KEY);
  if (savedJoiningMode && romanizerJoiningModeSelector) {
    romanizerJoiningMode = savedJoiningMode;
    romanizerJoiningModeSelector.value = savedJoiningMode;
    console.log(`從 localStorage 載入連詞模式: ${savedJoiningMode}`);
  }

  // --- Event Listeners ---
  // segmentation workspace 入口（腔調切換）
  if (romanizerDialectSelector) {
    romanizerDialectSelector.addEventListener('change', function() {
      romanizerSelectedDialect = this.value;
      console.log(`Romanizer 腔調已切換為: ${romanizerSelectedDialect}`);
      if (segmentationWorkspace) {
        segmentationWorkspace.innerHTML = '';
      }
      if (romanizerOutput) {
        romanizerOutput.innerHTML = '';
      }
      // After dialect change, user needs to manually re-segment.
    });
  }

  if (romanizerJoiningModeSelector) {
    romanizerJoiningModeSelector.addEventListener('change', function() {
      romanizerJoiningMode = this.value;
      localStorage.setItem(ROMANIZER_JOINING_MODE_KEY, romanizerJoiningMode);
      console.log(`連詞模式已切換並儲存: ${romanizerJoiningMode}`);

      // 淨更新分隔符，毋儲存到歷史紀錄
      updateJoiningSeparators();
      applyPunctuationSpacing(); // 【新】加上這行
    });
  }

  if (showRomanizerBtn) {
    showRomanizerBtn.addEventListener('click', showRomanizer);
  }
  if (romanizerCloseBtn) {
    romanizerCloseBtn.addEventListener('click', hideRomanizer);
  }
  // segmentation 入口（自動）
  if (romanizerStartBtn) {
    romanizerStartBtn.addEventListener('click', startSegmentation);
  }
  // segmentation 入口（手動）
  if (segmentationWorkspace) {
    segmentationWorkspace.addEventListener('click', handleSegmentClick);
  }
  if (copyRomanizerResultBtn) {
    copyRomanizerResultBtn.addEventListener('click', copyRomanizerResult);
  }
  // segmentation 入口（Undo/Redo）
  if (romanizerUndoBtn) {
    romanizerUndoBtn.addEventListener('click', undo);
  }
  if (romanizerRedoBtn) {
    romanizerRedoBtn.addEventListener('click', redo);
  }

  if (romanizerOutput) {
    romanizerOutput.addEventListener('click', function(event) {
      const target = event.target;
      const uppercaseBtn = target.closest('.uppercase-btn');
      const deleteBtn = target.closest('.delete-btn');

      if (uppercaseBtn) {
        const wrapper = uppercaseBtn.parentNode;
        // 【新】為這粒音節加上手動設定个標籤
        wrapper.dataset.manualCase = 'true'; 
        const textNode = Array.from(wrapper.childNodes).find(n => n.nodeType === Node.TEXT_NODE);
        if (textNode) {
            const currentText = textNode.textContent;
            if (currentText[0] === currentText[0].toUpperCase()) {
                textNode.textContent = currentText.toLowerCase();
            } else {
                textNode.textContent = currentText.charAt(0).toUpperCase() + currentText.slice(1);
            }
            // 手動調整後，毋使呼叫 applyCapitalizationRules，直接儲存狀態
            saveState();
        }
      } 
      else if (deleteBtn) {
        const wrapper = deleteBtn.parentNode;
        const prevNode = wrapper.previousSibling;
        const nextNode = wrapper.nextSibling;

        // 優先處理音節之間个分隔符 (hyphen 或 apostrophe)
        if (nextNode && nextNode.nodeType === Node.TEXT_NODE && /^\s*[-']/.test(nextNode.textContent)) {
          nextNode.remove();
        } else if (prevNode && prevNode.nodeType === Node.TEXT_NODE && /[-']\s*$/.test(prevNode.textContent)) {
          prevNode.remove();
        }

        const prevEl = wrapper.previousElementSibling;
        const nextEl = wrapper.nextElementSibling;
        wrapper.remove();

        // 後續清理：處理孤單个斜線摎空括弧
        if (prevEl && nextEl) {
          const prevText = prevEl.textContent.trim();
          const nextText = nextEl.textContent.trim();
          // 情況一：刪忒後淨剩下空括弧: 【】
          if (("【（(".includes(prevText)) && ("】）)".includes(nextText))) {
            prevEl.remove();
            nextEl.remove();
          }
          // 情況二：刪忒後斜線變做括弧个頭: 【/sii】 -> 【sii】
          else if (("【（(".includes(prevText)) && nextText === '/') {
            nextEl.remove();
          }
          // 情況三：刪忒後斜線變做括弧个尾: 【sii/】 -> 【sii】
          else if (prevText === '/' && ("】）)".includes(nextText))) {
            prevEl.remove();
          }
        }
        saveState();
        updateJoiningSeparators();
        applyPunctuationSpacing(); // 【新】加上這行
        if (typeof adjustRomanizerOutputFontSize === 'function') adjustRomanizerOutputFontSize();
      }
    });
  }

  // --- Functions ---
  function showRomanizer() {
    if (romanizerContainer) {
      romanizerContainer.classList.add('is-visible');
      if (typeof currentActiveMainDialectName !== 'undefined' && romanizerDialectSelector) {
        const mainDialect = currentActiveMainDialectName;
        const isValidOption = Array.from(romanizerDialectSelector.options).some(opt => opt.value === mainDialect);
        const dialectToSet = (mainDialect && isValidOption) ? mainDialect : '四縣';
        romanizerDialectSelector.value = dialectToSet;
        romanizerSelectedDialect = romanizerDialectSelector.value;
        console.log(`Romanizer opened. Dialect set to: ${romanizerSelectedDialect}`);
      }

      // 【新】加上 GA 事件追蹤
      trackEvent('open', 'Romaine', 'open_container');

      // 【新】為 Firefox 調整字體大小
      if (typeof adjustRomanizerOutputFontSize === 'function') {
        // 延遲執行，確保 modal 顯示動畫完成後再計算闊度
        setTimeout(adjustRomanizerOutputFontSize, 150);
      }
    }
  }

  function hideRomanizer() {
    if (romanizerContainer) {
      romanizerContainer.classList.remove('is-visible');
    }
  }
  
  document.addEventListener('closeRomanizer', hideRomanizer);

  function handleSegmentClick(event) {
        const target = event.target;
        const resegmentBtn = target.closest('.resegment-btn');
        const segmentWordSpan = target.closest('.segment-word');
    
        if (resegmentBtn && segmentWordSpan) {
          event.stopPropagation();
          initiateResegment(segmentWordSpan);
        } 
        else if (segmentWordSpan) {
          const searchText = segmentWordSpan.textContent;
    
          if (typeof findPronunciationsInAllData !== 'function' || typeof showPronunciationPopup !== 'function') {
            console.error('核心函式 (findPronunciationsInAllData 或 showPronunciationPopup) 未定義。');
            alert('核心查詢功能載入失敗，請重新整理頁面。');
            return;
          }
    
          const readings = findPronunciationsInAllData(searchText);
    
          // 【新邏輯】無論 readings 係無係空个，都直接呼叫 showPronunciationPopup
          // 函式內部自家會處理空陣列个情況
          showPronunciationPopup(searchText, readings, segmentWordSpan, (anchor, phonetic) => {
            updatePronunciationAndMark(anchor, phonetic);
          }, romanizerSelectedDialect);
        }
    }

  function createSegmentSpan(segmentText) {
    const segmentRegex = /([^\u4e00-\u9fa5\u3400-\u4dbf\u{20000}-\u{2a6df}\u{2a700}-\u{2b73f}\u{2b740}-\u{2b81f}\u{2b820}-\u{2ceaf}\u{2ceb0}-\u{2ebef}]+)/u;
    const span = document.createElement('span');
    span.textContent = segmentText;

    if (!segmentRegex.test(segmentText)) {
      span.classList.add('segment-word');
      const readings = findPronunciationsInAllData(segmentText);
      const exactMatches = readings.filter(r => r.isExactMatch);

      if (exactMatches.length > 0) {
        const dialectSpecificMatches = exactMatches.filter(r => isSourceMatchingDialect(r.source, romanizerSelectedDialect));
        if (dialectSpecificMatches.length > 0) {
          span.dataset.romanized = dialectSpecificMatches[0].pronunciation;
          span.classList.add('completed');
          const uniquePronunciations = [...new Set(dialectSpecificMatches.map(r => r.pronunciation))];
          if (uniquePronunciations.length > 1) {
            span.classList.add('auto-filled-multiple');
          }
        } else {
          span.dataset.romanized = '';
          span.classList.add('no-result');
        }
      } else {
        span.dataset.romanized = '';
        span.classList.add('no-result');
      }

      if (segmentText.length > 1 && span.classList.contains('no-result')) {
        span.classList.add('multichar');
        const resegmentBtn = document.createElement('button');
        resegmentBtn.className = 'resegment-btn';
        resegmentBtn.innerHTML = '<i class="fas fa-cut"></i>';
        resegmentBtn.title = '重新斷詞';
        resegmentBtn.setAttribute('aria-label', '重新斷詞');
        span.appendChild(resegmentBtn);
      }
    }
    return span;
  }

  function startSegmentation() {
    // 【新】加上 GA 事件追蹤
    trackEvent('click', 'Romaine', 'start_segmentation');

    if (!romanizerInput || !segmentationWorkspace || !romanizerOutput) return;

    segmentationWorkspace.innerHTML = '';
    romanizerOutput.innerHTML = '';

    const text = romanizerInput.value;
    if (!text) return;

    const lines = text.split('\n');

    lines.forEach((line, lineIndex) => {
      let suppressCapitalization = false;
      if (line.startsWith("'")) {
        suppressCapitalization = true;
        line = line.substring(1);
      }

      const segmentRegex = /([^\u4e00-\u9fa5\u3400-\u4dbf\u{20000}-\u{2a6df}\u{2a700}-\u{2b73f}\u{2b740}-\u{2b81f}\u{2b820}-\u{2ceaf}\u{2ceb0}-\u{2ebef}]+)/u;
      const segments = line.split(segmentRegex).filter(Boolean);

      segments.forEach((segment, segmentIndex) => {
        const span = createSegmentSpan(segment);
        if (segmentIndex === 0 && suppressCapitalization) {
          span.dataset.noCapitalize = 'true';
        }
        segmentationWorkspace.appendChild(span);
      });

      if (lineIndex < lines.length - 1) {
        segmentationWorkspace.appendChild(document.createElement('br'));
      }
    });

    updateAllRomanizerOutput();
  }

  function initiateResegment(spanToEdit) {
    const originalText = spanToEdit.textContent;
    // 【新】儲存舊个 segId
    const originalSegId = spanToEdit.dataset.segId;

    const input = document.createElement('input');
    input.type = 'text';
    input.value = originalText;
    input.className = 'resegment-input';
    input.style.width = `${spanToEdit.offsetWidth + 10}px`;
    // 【新】將 segId 傳分 input element
    input.dataset.originalSegId = originalSegId;
    // PATCH: 儲存 noCapitalize flag
    if (spanToEdit.dataset.noCapitalize) {
      input.dataset.hadNoCapitalize = 'true';
    }

    // 重新分配 workspace 內底个 ID，避免衝突
    const newIdPrefix = `${originalSegId}-${Date.now()}`;
    spanToEdit.dataset.segId = newIdPrefix + '-0';

    spanToEdit.replaceWith(input);
    input.focus();
    input.select();

    input.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            // 拿掉 blur 監聽器，避免重複執行 confirm/cancel
            input.removeEventListener('blur', handleBlur);
            confirmResegment(input);
        } else if (e.key === 'Escape') {
            cancelResegment(input, spanToEdit);
        }
    });

    const handleBlur = () => {
        cancelResegment(input, spanToEdit);
    };
    input.addEventListener('blur', handleBlur, { once: true });
  }

  function confirmResegment(inputElement) {
        const originalSegId = inputElement.dataset.originalSegId;
        const newText = inputElement.value.trim();
        const workspaceSpansFragment = document.createDocumentFragment();
        // PATCH: 讀取 noCapitalize flag
        const hadNoCapitalize = inputElement.dataset.hadNoCapitalize === 'true';
    
        // 【舊个記憶邏輯已刪除】
    
        // 1. 更新 workspace
        if (newText) {
            const newSegments = newText.split(/\s+/).filter(Boolean);
            newSegments.forEach((segment, index) => {
                const newSpan = createSegmentSpan(segment);
                newSpan.dataset.segId = `${originalSegId}-${index}`;
                // PATCH: 若原始 span 有 noCapitalize，加轉分詞後个第一個 span
                if (index === 0 && hadNoCapitalize) {
                    newSpan.dataset.noCapitalize = 'true';
                }
                workspaceSpansFragment.appendChild(newSpan);
            });
        }
        inputElement.replaceWith(workspaceSpansFragment);
    
        const groupToUpdate = romanizerOutput.querySelector(`.segment-group[data-seg-id="${originalSegId}"]`);
    
        if (groupToUpdate) {
            groupToUpdate.innerHTML = '';
            const outputFragment = document.createDocumentFragment();
            const newWorkspaceSpans = Array.from(segmentationWorkspace.querySelectorAll(`[data-seg-id^="${originalSegId}-"]`));
    
            newWorkspaceSpans.forEach(span => {
                if (span.classList.contains('segment-word')) {
                    const subSegmentWrapper = document.createElement('span');
                    subSegmentWrapper.dataset.segId = span.dataset.segId;
    
                    if (span.dataset.romanized) {
                        populateSegmentGroup(subSegmentWrapper, span.dataset.romanized, span);
                    } else {
                        const placeholder = document.createElement('span');
                        placeholder.className = 'placeholder-block';
                        subSegmentWrapper.appendChild(placeholder);
                    }
                    outputFragment.appendChild(subSegmentWrapper);
                } else {
                    const puncText = normalizePunctuation(span.textContent);
                    outputFragment.appendChild(document.createTextNode(puncText));
                }
            });
            groupToUpdate.appendChild(outputFragment);
        } else if (newText) {
            console.warn(`尋無 ID 為: ${originalSegId} 个 segment group 來更新。`);
        }
    
        // 5. 重新套用全局規則
        applyCapitalizationRules();
        updateJoiningSeparators();
        applyPunctuationSpacing();
        if (typeof adjustRomanizerOutputFontSize === 'function') adjustRomanizerOutputFontSize();
    
        // 【舊个還原邏輯已刪除】
    
        saveState();
    }

  function cancelResegment(inputElement, originalSpan) {
    if (document.body.contains(inputElement)) {
      inputElement.replaceWith(originalSpan);
    }
  }

  function copyRomanizerResult() {
    if (!romanizerOutput || !copyRomanizerResultBtn) return;

    const clone = romanizerOutput.cloneNode(true);
    clone.querySelectorAll('.uppercase-btn, .delete-btn').forEach(btn => btn.remove());

    const textToCopy = clone.textContent.replace(/\s+/g, ' ').trim();

    if (textToCopy) {
      navigator.clipboard.writeText(textToCopy).then(() => {
        const originalButtonContent = copyRomanizerResultBtn.innerHTML;
        copyRomanizerResultBtn.innerHTML = '<i class="fas fa-check"></i> 已複製';
        copyRomanizerResultBtn.disabled = true;
        setTimeout(() => {
          copyRomanizerResultBtn.innerHTML = originalButtonContent;
          copyRomanizerResultBtn.disabled = false;
        }, 2000);
      }).catch(err => {
        console.error('無法複製文字: ', err);
        alert('複製失敗，請手動複製。');
      });
    }
  }

  function updatePronunciationAndMark(targetSpan, selectedRomanization) {
        if (!targetSpan || !targetSpan.dataset.segId) return;
    
        document.querySelectorAll('#segmentation-workspace .just-substituted').forEach(el => {
            el.classList.remove('just-substituted');
        });
    
        targetSpan.dataset.romanized = selectedRomanization;
        targetSpan.classList.add('completed', 'just-substituted');
        targetSpan.classList.remove('auto-filled-multiple', 'no-result');
    
        const segId = targetSpan.dataset.segId;
        const elementToUpdate = romanizerOutput.querySelector(`[data-seg-id="${segId}"]`);
    
        if (elementToUpdate) {
            populateSegmentGroup(elementToUpdate, selectedRomanization, targetSpan);
    
            // 重新套用全局規則
            applyCapitalizationRules();
            updateJoiningSeparators();
            applyPunctuationSpacing();
            if (typeof adjustRomanizerOutputFontSize === 'function') adjustRomanizerOutputFontSize();
    
            saveState();
        } else {
            console.error(`無法在 output 區內尋著帶有 seg-id="${segId}" 个元素來更新。`);
        }
    
        targetSpan.classList.remove('just-substituted');
    }

  function normalizePunctuation(punc) {
    const punctuationMap = {
      '，': ',', '。': '.', '？': '?', '！': '!', '；': ';', '：': ':',
      '（': '(', '）': ')', '、': ',',
      '「': '“', '」': '”', '『': '‘', '』': '’'
    };
    let result = '';
    for (let i = 0; i < punc.length; i++) {
      result += punctuationMap[punc[i]] || punc[i];
    }
    return result;
  }

  function tokenizeRomanization(text) {
    if (!text) return [];
    return text.match(/[【】（）()\/]|[^【】（）()\/\s]+/g) || [];
  }

  function applyApostropheRules(spaceSeparatedSyllables) {
    if (!spaceSeparatedSyllables) return '';
    let text = spaceSeparatedSyllables;
    const rules = [
      { find: /([bdgmn]) ([aáǎàāâeéěèēêiíǐìīîoóǒòōôuúǔùūû])/g, replace: "$1'$2" },
      { find: /([aáǎàāâ]) ([iíǐìīîuúǔùūû])/g, replace: "$1'$2" },
      { find: /([eéěèēê]) ([uúǔùūû])/g, replace: "$1'$2" },
      { find: /([iíǐìīî]) ([aáǎàāâeéěèēêiíǐìīîoóǒòōôuúǔùūû])/g, replace: "$1'$2" },
      { find: /([oóǒòōô]) ([iíǐìīî])/g, replace: "$1'$2" },
      { find: /([uúǔùūû]) ([aáǎàāâeéěèēêiíǐìīî])/g, replace: "$1'$2" },
      { find: /([aáǎàāâeéěèēêiíǐìīîoóǒòōôuúǔùūû]) ([nńňǹ]g)/g, replace: "$1'$2" },
      { find: /(n) (g)/g, replace: "$1'$2" }
    ];
    rules.forEach(rule => {
      text = text.replace(rule.find, rule.replace);
    });
    return text.replace(/\s/g, '');
  }

  function populateSegmentGroup(container, romanizedText, sourceSpan) {
        container.innerHTML = '';
        const tokens = tokenizeRomanization(romanizedText);
    
        tokens.forEach(token => {
            if (!/[【】（）()\/]/.test(token)) {
                // 【新邏輯】淨產生音節个 wrapper，毋產生連接符號
                const wrapper = document.createElement('span');
                wrapper.className = 'syllable-wrapper';
                if (sourceSpan.classList.contains('just-substituted')) {
                    wrapper.classList.add('substituted-by-user');
                }
                if (sourceSpan.dataset.noCapitalize) {
                    wrapper.dataset.noCapitalize = 'true';
                }
                wrapper.appendChild(document.createTextNode(token));
    
                const uppercaseBtn = document.createElement('button');
                uppercaseBtn.className = 'uppercase-btn';
                uppercaseBtn.textContent = 'U';
                uppercaseBtn.setAttribute('aria-label', `將 ${token} 轉做大寫`);
    
                const deleteBtn = document.createElement('button');
                deleteBtn.className = 'delete-btn';
                deleteBtn.innerHTML = '<i class="fas fa-times"></i>';
                deleteBtn.setAttribute('aria-label', `刪除 ${token}`);
    
                wrapper.appendChild(uppercaseBtn);
                wrapper.appendChild(deleteBtn);
                container.appendChild(wrapper);
            } else {
                // 分隔符號 (像【】) 還係愛保留
                const separatorSpan = document.createElement('span');
                separatorSpan.className = 'separator';
                separatorSpan.textContent = token;
                container.appendChild(separatorSpan);
            }
        });
    }

  function applyCapitalizationRules() {
    if (!romanizerOutput) return;

    // 步驟一：重設，淨將無手動標籤个音節轉做細寫
    const allSyllableWrappers = romanizerOutput.querySelectorAll('.syllable-wrapper');
    allSyllableWrappers.forEach(wrapper => {
        // 【新】若係有手動標籤，就跳過毋處理
        if (wrapper.dataset.manualCase) {
            return;
        }
        const textNode = Array.from(wrapper.childNodes).find(n => n.nodeType === Node.TEXT_NODE);
        if (textNode) {
            const currentText = textNode.textContent;
            if (currentText && currentText.length > 0) {
                textNode.textContent = currentText.charAt(0).toLowerCase() + currentText.slice(1);
            }
        }
    });

    // 步驟二：根據句首規則，重新設定大寫
    let capitalizeNext = true;
    const outputNodes = Array.from(romanizerOutput.childNodes);

    for (const node of outputNodes) {
        if (node.nodeName === 'BR') {
            capitalizeNext = true;
            continue;
        }
        if (node.nodeType === Node.TEXT_NODE) {
            const text = node.textContent.trim();
            if (text.endsWith('.') || text.endsWith('?') || text.endsWith('!')) {
                capitalizeNext = true;
            }
            continue;
        }
        if (node.nodeType === Node.ELEMENT_NODE && node.classList.contains('segment-group')) {
            const firstSyllableInGroup = node.querySelector('.syllable-wrapper');
            if (firstSyllableInGroup) {
                // 【新】愛確定無手動標籤，正做自動大寫
                if (capitalizeNext && !firstSyllableInGroup.dataset.manualCase && !firstSyllableInGroup.dataset.noCapitalize) {
                    const textNode = Array.from(firstSyllableInGroup.childNodes).find(n => n.nodeType === Node.TEXT_NODE);
                    if (textNode) {
                        const text = textNode.textContent;
                        textNode.textContent = text.charAt(0).toUpperCase() + text.slice(1);
                    }
                }
                capitalizeNext = false;
            }
        }
    }
  }

function applyPunctuationSpacing(){
    if (!romanizerOutput) return;

    let finalHTML = romanizerOutput.innerHTML;

    // 【全新規則組】
    // 規則 1: 在後引號和開引號之間加上闊位 e.g. ")(" -> ") ("
    finalHTML = finalHTML.replace(/([”’)}\]])([“‘(\[{])/g, '$1 $2');

    // 規則 2: 在一個詞 (</span>) 和一個開引號之間加上闊位 e.g. "</span>(" -> "</span> ("
    finalHTML = finalHTML.replace(/(<\/span>)([“‘(\[{])/g, '$1 $2');

    // 規則 3: 拿忒「開引號」後壁个闊位 e.g. "( " -> "("
    finalHTML = finalHTML.replace(/([“‘(\[{])\s+/g, '$1');

    // 規則 4: 拿忒「後引號」還有一般標點頭前个闊位 e.g. " ," -> ","
    finalHTML = finalHTML.replace(/\s+([,.?!:;”’)}\]])/g, '$1');

    // 規則 5: 在「後引號」還有一般標點後壁加上一個闊位，並避免在連續標點之間也加闊位
    finalHTML = finalHTML.replace(/([,.?!:;”’)}\]])(?![\n,.?!:;”’)}\]])/g, '$1 ');

    romanizerOutput.innerHTML = finalHTML.trim();
}

/**
 * 淨更新 output 區內底个音節連詞符，毋影響音節本身。
 * 這擺會正確處理 .segment-group 內底个結構。
 */
function updateJoiningSeparators() {
    if (!romanizerOutput) return;

    // 步驟 1: 拿忒所有舊个連接符號 (文字節點)
    const textNodesToRemove = [];
    const walker = document.createTreeWalker(romanizerOutput, NodeFilter.SHOW_TEXT);
    let node;
    while (node = walker.nextNode()) {
        if (/^[\s'-]+$/.test(node.textContent) && node.parentNode.closest('.segment-group')) {
            textNodesToRemove.push(node);
        }
    }
    textNodesToRemove.forEach(n => n.remove());

    // 步驟 2: 對每一隻 segment-group 做獨立處理
    const segmentGroups = romanizerOutput.querySelectorAll('.segment-group');
    segmentGroups.forEach(group => {
        const syllables = Array.from(group.querySelectorAll('.syllable-wrapper'));
        if (syllables.length <= 1) return;

        // 步驟 3: 尋出所有个「障礙物」
        const nonSyllableElements = Array.from(group.querySelectorAll('.separator'));
        const puncWalker = document.createTreeWalker(group, NodeFilter.SHOW_TEXT);
        const punctuationNodes = [];
        let puncNode;
        while (puncNode = puncWalker.nextNode()) {
            // 淨愛無係闊位、而且毋係在音節內部个文字節點
            if (!/^\s*$/.test(puncNode.textContent) && !puncNode.parentNode.closest('.syllable-wrapper')) {
                punctuationNodes.push(puncNode);
            }
        }
        const obstacles = [...nonSyllableElements, ...punctuationNodes];

        // 步驟 4: 檢查每一對相鄰个音節之間係無係有障礙物
        for (let i = 0; i < syllables.length - 1; i++) {
            const s1 = syllables[i];
            const s2 = syllables[i + 1];

            const hasObstacle = obstacles.some(obs =>
                (s1.compareDocumentPosition(obs) & Node.DOCUMENT_POSITION_FOLLOWING) &&
                (s2.compareDocumentPosition(obs) & Node.DOCUMENT_POSITION_PRECEDING)
            );

            // 若係無障礙物，正插入連接符號
            if (!hasObstacle) {
                const s1TextNode = Array.from(s1.childNodes).find(n => n.nodeType === Node.TEXT_NODE);
                const s2TextNode = Array.from(s2.childNodes).find(n => n.nodeType === Node.TEXT_NODE);

                if (s1TextNode && s2TextNode) {
                    const s1Text = s1TextNode.textContent.toLowerCase();
                    const s2Text = s2TextNode.textContent.toLowerCase();
                    let separator = '';

                    switch (romanizerJoiningMode) {
                        case 'hyphen': separator = '-'; break;
                        case 'space': separator = ' '; break;
                        case 'none':
                            const tempString = applyApostropheRules(`${s1Text} ${s2Text}`);
                            if (tempString.includes("'")) separator = "'";
                            break;
                    }

                    if (separator) {
                        s1.after(document.createTextNode(separator));
                    }
                }
            }
        }
    });
}

  function updateAllRomanizerOutput() {
    if (!romanizerOutput || !segmentationWorkspace) return;
    romanizerOutput.innerHTML = '';
    const childNodes = Array.from(segmentationWorkspace.childNodes);
    let segIdCounter = 0;

    childNodes.forEach(node => {
      if (node.nodeName === 'BR') {
        romanizerOutput.appendChild(document.createElement('br'));
        return;
      }
      if (node.nodeType === Node.ELEMENT_NODE && node.tagName === 'SPAN') {
        const span = node;
        const currentSegId = `seg-${segIdCounter++}`;
        span.dataset.segId = currentSegId;

        if (span.classList.contains('no-result')) {
          const segmentGroup = document.createElement('span');
          segmentGroup.className = 'segment-group';
          segmentGroup.dataset.segId = currentSegId;
          const placeholder = document.createElement('span');
          placeholder.className = 'placeholder-block';
          segmentGroup.appendChild(placeholder);
          romanizerOutput.appendChild(segmentGroup);
        } else if (span.dataset.romanized) {
          const segmentGroup = document.createElement('span');
          segmentGroup.className = 'segment-group';
          segmentGroup.dataset.segId = currentSegId;
          populateSegmentGroup(segmentGroup, span.dataset.romanized, span);
          romanizerOutput.appendChild(segmentGroup);
        } else {
          const puncText = normalizePunctuation(span.textContent);
          romanizerOutput.appendChild(document.createTextNode(puncText));
        }
      }
    });

    // 【關鍵修改】拿忒舊个正規表示式闊位處理，改呼叫新函式
    applyCapitalizationRules();
    updateJoiningSeparators();
    applyPunctuationSpacing(); // 【新】加上這行
    if (typeof adjustRomanizerOutputFontSize === 'function') adjustRomanizerOutputFontSize();
    saveState(true);

    document.querySelectorAll('#segmentation-workspace .just-substituted').forEach(el => {
      el.classList.remove('just-substituted');
    });
  }

  // --- History Functions ---
  function saveState(isNewSegmentation = false) {
    if (!romanizerOutput) return;
    const currentState = romanizerOutput.innerHTML;

    if (isNewSegmentation) {
      history = [currentState];
      historyIndex = 0;
      updateUndoRedoButtons();
      return;
    }

    if (history.length > 0 && history[historyIndex] === currentState) {
      return;
    }

    if (historyIndex < history.length - 1) {
      history = history.slice(0, historyIndex + 1);
    }

    history.push(currentState);
    historyIndex++;
    updateUndoRedoButtons();
  }

  function undo() {
    if (historyIndex > 0) {
      historyIndex--;
      romanizerOutput.innerHTML = history[historyIndex];
      updateUndoRedoButtons();
      // PATCH: 還原後重新套用規則，確保一致性
      applyCapitalizationRules();
      updateJoiningSeparators();
      applyPunctuationSpacing(); // 【新】加上這行
      if (typeof adjustRomanizerOutputFontSize === 'function') adjustRomanizerOutputFontSize();
    }
  }

  function redo() {
    if (historyIndex < history.length - 1) {
      historyIndex++;
      romanizerOutput.innerHTML = history[historyIndex];
      updateUndoRedoButtons();
      // PATCH: 還原後重新套用規則，確保一致性
      applyCapitalizationRules();
      updateJoiningSeparators();
      applyPunctuationSpacing(); // 【新】加上這行
      if (typeof adjustRomanizerOutputFontSize === 'function') adjustRomanizerOutputFontSize();
    }
  }

  function updateUndoRedoButtons() {
    if (!romanizerUndoBtn || !romanizerRedoBtn) return;
    romanizerUndoBtn.disabled = historyIndex <= 0;
    romanizerRedoBtn.disabled = historyIndex >= history.length - 1;
  }
});